exercise.referenceSolution:
struct Base { virtual int read() const = 0; virtual ~Base() = default; };
class Fixed final : public Base { int value_; public: explicit Fixed(int x) : value_(x) {} int read() const override { return value_; } };
int solve(int a,int b) { Fixed x{a},y{b}; const Base& p=x; const Base& q=y; return p.read()-q.read(); }
